from collections import Counter

class Solution:
    def makeAntiPalindrome(self, s: str) -> str:
        n = len(s)
        if max(Counter(s).values()) > n // 2:
            return "-1"
        t = sorted(s)
        for i in range(n // 2):
            if t[i] == t[n - 1 - i]:
                for j in range(n // 2, n):
                    if t[j] != t[i] and t[n - 1 - j] != t[i]:
                        t[i], t[j] = t[j], t[i]
                        break
        return ''.join(t)

