        for (int c = 0; c < 26; c++)
            if (cnt[c] > n / 2) return "-1";
        sort(s.begin(), s.end());
        for (int i = 0; i < n / 2; i++)
            if (s[i] == s[n - 1 - i])
                for (int j = n / 2; j < n; j++)
                    if (s[j] != s[i] && s[n - 1 - j] != s[i]) {
                        swap(s[i], s[j]);
                        break;
                    }
        return s;
    }
};

