class Solution:
    def makeAntiPalindrome(self, s: str) -> str:
        from collections import Counter
        n = len(s)
        cnt = Counter(s)
        if max(cnt.values()) > n // 2:
            return "-1"
        res = [''] * n
        avail = sorted(cnt.elements())
        import heapq
        heap = [(c, ch) for ch, c in cnt.items()]
        heapq.heapify(heap)
        used = Counter()
        for i in range(n // 2):
            c, ch = heapq.heappop(heap)
            res[i] = ch
            used[ch] += 1
            if cnt[ch] - used[ch] > 0:
                heapq.heappush(heap, (c + 1, ch))
        rest = []
        for ch in sorted(cnt):
            rest.extend([ch] * (cnt[ch] - used[ch]))
        ri = 0
        for i in range(n // 2 - 1, -1, -1):
            while rest[ri] == res[i]:
                ri += 1
            res[n - 1 - i] = rest[ri]
            ri += 1
        return ''.join(res)

