class Solution {
    public String makeAntiPalindrome(String s) {
        int n = s.length(), cnt[] = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        for (int c = 0; c < 26; c++)
            if (cnt[c] > n / 2) return "-1";
        char[] res = new char[n];
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        for (int c = 0; c < 26; c++) if (cnt[c] > 0) pq.offer(new int[]{0, c});
        int[] used = new int[26];
        for (int i = 0; i < n / 2; i++) {
            int[] top = pq.poll();
            res[i] = (char) ('a' + top[1]);
            used[top[1]]++;
            if (used[top[1]] < cnt[top[1]]) pq.offer(new int[]{used[top[1]], top[1]});
        }
        StringBuilder rs = new StringBuilder();
        for (int c = 0; c < 26; c++)
            for (int t = 0; t < cnt[c] - used[c]; t++) rs.append((char) ('a' + c));
        String rest = rs.toString();
        int ri = 0;
        for (int i = n / 2 - 1; i >= 0; i--) {
            while (rest.charAt(ri) == res[i]) ri++;
            res[n - 1 - i] = rest.charAt(ri++);
        }
        return new String(res);
    }
}

